HOS_HTML = '<article class="article-item " role="article">\n            <span class="item-index">۳.</span>\n        <h2 class="heading">\n            <a href="/fa/article/475321/%D9%86%D8%B3%D8%A8%D8%AA-%D8%A7%D8%AD%DA%A9%D8%A7%D9%85-%D9%86%D8%AC%D9%88%D9%85-%D8%A8%D8%A7-%D8%B7%D8%A8-%D8%AC%D8%A7%D9%84%DB%8C%D9%86%D9%88%D8%B3%DB%8C-%D8%AF%D8%B1-%D8%AA%D8%A7%D8%B1%DB%8C%D8%AE-%D9%85%DB%8C%D8%A7%D9%86%D9%87-%D8%A7%DB%8C%D8%B1%D8%A7%D9%86">نسبت احکام نجوم با طب جالینوسی در تاریخ میانه ایران<span class="scientific-rank">(مقاله علمی وزارت علوم)</span></a>        </h2>\n        <div class="details">\n                    <div class="authors">\n                                                            <b>نویسنده:</b>\n                                                    <a href="/fa/article/author/108069" rel="author">فاطمه زرگری</a>                                                                        </div>\n                                    <div class="journal">\n                <b>منبع:</b>\n                <a class="journal-title" href="/fa/article/journal-number/53651/%D8%AA%D8%A7%D8%B1%DB%8C%D8%AE-%D8%B9%D9%84%D9%85-%D8%AF%D9%88%D8%B1%D9%87-19-%D8%A8%D9%87%D8%A7%D8%B1-%D9%88-%D8%AA%D8%A7%D8%A8%D8%B3%D8%AA%D8%A7%D9%86-1400-%D8%B4%D9%85%D8%A7%D8%B1%D9%87-1-%D9%BE%DB%8C%D8%A7%D9%BE%DB%8C-30-">تاریخ علم دوره ۱۹ بهار و تابستان ۱۴۰۰ شماره ۱ (پیاپی ۳۰)</a>                                    <small class="page-number">\n                        1 - 25                    </small>\n                            </div>\n        \n        \n            \t<p class="tags">\n\t\t<span><i class="fa fa-tag"></i> کلیدواژه\u200cها: </span>\n                    <a class="tag" href="/fa/tag/72794/%D8%A7%DB%8C%D8%B1%D8%A7%D9%86+%D8%B9%D8%B5%D8%B1+%D9%85%DB%8C%D8%A7%D9%86%D9%87">ایران عصر میانه</a>                    <a class="tag" href="/fa/tag/133162/%D8%AA%D9%86%D8%AC%DB%8C%D9%85">تنجیم</a>                    <a class="tag" href="/fa/tag/15287/%D8%AF%D8%B1%D9%85%D8%A7%D9%86">درمان</a>                    <a class="tag" href="/fa/tag/302685/%D8%B1%D9%88%DB%8C%DA%A9%D8%B1%D8%AF+%D8%AF%D8%B1%D9%85%D8%A7%D9%86%DB%8C+%D8%AC%D8%A7%D9%84%DB%8C%D9%86%D9%88%D8%B3%DB%8C">رویکرد درمانی جالینوسی</a>                    <a class="tag" href="/fa/tag/302686/%D8%B3%D8%A8%D8%A8+%D8%B4%D9%86%D8%A7%D8%B3%DB%8C+%D8%A8%DB%8C%D9%85%D8%A7%D8%B1%DB%8C">سبب شناسی بیماری</a>        \t</p>\n                        <div class="buttons">\n                            <span>\n                    <b>تعداد بازدید : </b>\n                    ۵۷۴                </span>\n                                                            <button type="button" class="btn btn-primary" data-toggle="collapse" data-target="#article-abstract-475321">چکیده</button>                                                        <a class="btn btn-primary" href="/fa/article/download/475321"><i class="fa fa-download"></i></a>                <span>\n                    <b>تعداد دانلود : </b>\n                    ۵۱۶                </span>\n                    </div>\n                                            <div id="article-abstract-475321" class="well collapse ">\n                مواجهه جامعه عصر میانه با پدیده بیماری در سه بخش علت یابی، فرایند درمان و راه های پیشگیری در قالب سه رویکرد دینی، جالینوسی و عامیانه قابل ارزیابی است. اساس طب جالینوسی بر متعادل نگه داشتن اخلاط چهارگانه استوار است. روش علت یابی و درمان در این رویکرد مبتنی بر معاینه بیمار است. موضوع تنجیم یا احکام نجوم تفسیر نحوه اثرگذاری اجرام سماوی بر دنیای تحت قمر است. اگرچه در غالب موارد کارکرد تنجیم در ارتباط با سیاست و تقدیرگرایی دانسته می شود اما با بررسی متون تاریخی و پزشکی این دوران می توان کارکرد دیگری برای تنجیم در نظر گرفت. بر این اساس پرسش اصلی این مقاله این است که کارکرد تنجیم در طب جالینوسی چیست؟ در این تحقیق از روش تاریخی به منظور توصیف و تحلیل داده ها استفاده شده است. یافته های تحقیق نشان می دهد تنجیم در پیوند با رویکرد درمانی جالینوسی به ویژه در دو بخش علت یابی و درمان بیماری اثرگذار بوده است. شواهد عینی تاریخی نیز نشان دهنده مقبولیت و کاربرد این ترکیب در جامعه دوره میانه است.            </div>\n            </div>\n</article>\n<article class="article-item " role="article">\n            <span class="item-index">۵.</span>\n        <h2 class="heading">\n            <a href="/fa/article/182095/%D8%B2%DB%8C%D8%AC-%D9%85%D8%B9%D8%AA%D8%A8%D8%B1-%D8%B3%D9%86%D8%AC%D8%B1%DB%8C-%D8%AC%D8%A7%DB%8C%DA%AF%D8%A7%D9%87-%D9%88-%D8%A7%D9%87%D9%85%DB%8C%D8%AA-%D8%A2%D9%86-%D8%AF%D8%B1-%D8%AA%D8%A7%D8%B1%DB%8C%D8%AE-%D9%86%D8%AC%D9%88%D9%85-%D8%AF%D9%88%D8%B1%D9%87-%D8%A7%D8%B3%D9%84%D8%A7%D9%85%DB%8C">زیج معتبر سنجری ، جایگاه و اهمیت آن در تاریخ نجوم دوره اسلامی</a>        </h2>\n        <div class="details">\n                    <div class="authors">\n                                                            <b>نویسنده:</b>\n                                                    <a href="/fa/article/author/109365" rel="author">حمیدرضا گیاهی یزدی</a>                                                                        </div>\n                                    <div class="journal">\n                <b>منبع:</b>\n                <a class="journal-title" href="/fa/article/journal-number/21030/%D8%AA%D8%A7%D8%B1%DB%8C%D8%AE-%D8%B9%D9%84%D9%85-%D9%BE%D8%A7%DB%8C%DB%8C%D8%B2-1382-%D8%B4%D9%85%D8%A7%D8%B1%D9%87-1">تاریخ علم پاییز ۱۳۸۲ شماره ۱</a>                                    <small class="page-number">\n                                            </small>\n                            </div>\n        \n        \n            \t<p class="tags">\n\t\t<span><i class="fa fa-tag"></i> کلیدواژه\u200cها: </span>\n                    <a class="tag" href="/fa/tag/132347/%D8%B2%DB%8C%D8%AC+%D9%85%D8%B9%D8%AA%D8%A8%D8%B1+%D8%B3%D9%86%D8%AC%D8%B1%DB%8C">زیج معتبر سنجری</a>                    <a class="tag" href="/fa/tag/132348/%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B1%D8%AD%D9%85%D8%A7%D9%86+%D8%AE%D8%A7%D8%B2%D9%86%DB%8C">عبدالرحمان خازنی</a>                    <a class="tag" href="/fa/tag/132349/%D8%B6%D8%A7%D8%A8%D8%B7%D9%87+%D8%B1%D9%88%DB%8C%D8%AA+%D9%87%D9%84%D8%A7%D9%84+%D9%85%D8%A7%D9%87">ضابطه رویت هلال ماه</a>        \t</p>\n                            <div class="article-specialty-fields">\n            <b>حوزه\u200cهای تخصصی: </b>\n        <ul>                    <li>\n                                    <a href="/fa/article/field/3363/%D8%AD%D9%88%D8%B2%D9%87-%D9%87%D8%A7%DB%8C-%D8%AA%D8%AE%D8%B5%D8%B5%DB%8C">حوزه\u200cهای تخصصی</a>                                    <a href="/fa/article/field/74/%D8%B9%D9%84%D9%88%D9%85-%D8%A7%D9%86%D8%B3%D8%A7%D9%86%DB%8C">علوم انسانی</a>                                    <a href="/fa/article/field/2009/%D8%B1%D9%88%D8%B4-%D8%B4%D9%86%D8%A7%D8%B3%DB%8C-%D8%B9%D9%84%D9%88%D9%85-%D8%A7%D9%86%D8%B3%D8%A7%D9%86%DB%8C-%D9%88-%D8%B7%D8%A8%DB%8C%D8%B9%DB%8C">روش شناسی علوم انسانی و طبیعی</a>                                <a class="active" href="/fa/article/field/3084/%D9%85%D8%B9%D8%B1%D9%81%D8%AA-%D8%B4%D9%86%D8%A7%D8%B3%DB%8C-%D8%B9%D9%84%D9%85-%D8%AA%D8%B9%D8%B1%DB%8C%D9%81-%D8%B9%D9%84%D9%85-%D8%AA%D8%A7%D8%B1%DB%8C%D8%AE-%D8%B9%D9%84%D9%85-%D9%85%D8%B1%D8%B2%DA%AF%D8%B0%D8%A7%D8%B1%DB%8C-%D8%B9%D9%84%D9%85-%D8%A8%D8%A7-%D8%BA%DB%8C%D8%B1-%D8%B9%D9%84%D9%85"><b>معرفت شناسی علم،تعریف علم، تاریخ علم، مرزگذاری علم با غیر علم</b></a>            </li>\n            </ul></div>\n                <div class="buttons">\n                            <span>\n                    <b>تعداد بازدید : </b>\n                    ۱۶۹۸                </span>\n                                                            <button type="button" class="btn btn-primary" data-toggle="collapse" data-target="#article-abstract-182095">چکیده</button>                                                        <a class="btn btn-primary" href="/fa/article/download/182095"><i class="fa fa-download"></i></a>                <span>\n                    <b>تعداد دانلود : </b>\n                    ۹۳۱                </span>\n                    </div>\n                                            <div id="article-abstract-182095" class="well collapse ">\n                زیج معتبر سنجرى اثر ارزشمند اخترشناس پرآوازهء ایرانى عبدالرحمان خازنى (525-475 ق / 82 0 1- 130 ام) جایگاه ممتازى در سده هاى میانى نجوم دورهء اسلأمى دارد، خازنى که در مرو مى زیست، در مقدمهء این زیج به این نکته اشاره مى کند که این زیج حاصل رصدهاى 35 سالهء او است. وى در مقدمه فهرستى از نوآورى هایش را در این زیج عرضه مى کند که مهمترین آنها دربارهء رؤیت هلأل ماه، نظریهء گرفتگى هاست. همچنین وى موارد برترى زیج معتبر را نسبت به زیج هاى قبلى بیان کرده است. این مقاله نسخه هاى خطى به جا مانده از زیج معتبر و بخشهاى مهم آن را بررسى مى کند. البته هر کدام از این بخشها، در نهایت کل زیج به بررسى و تحلیل دقیق تر نیاز دارد،            </div>\n            </div>\n</article>'

cands = ba._parse_ensani_results(SEARCH_HTML)
check("parser finds the fixture results", len(cands) == 3)
c0 = cands[0]
check("first candidate is کتابشناسی بیرونی",
      c0["title"] == "کتابشناسی بیرونی")
check("candidate index tag is persian:ensani",
      c0["index"] == "persian:ensani")
check("candidate url is the article page",
      c0["url"].startswith("https://ensani.ir/fa/article/191665/"))
check("candidate carries the direct PDF download route",
      c0["oa_pdf_url"] ==
      "https://ensani.ir/fa/article/download/191665")
check("candidate authors parsed", c0["authors"] == ["احمد شعبانی"])
check("candidate year converts Persian digits",
      c0["year"] == 1368)
check("candidate venue names the journal issue",
      "تحقیقات کتابداری" in c0["venue"])

hos = ba._parse_ensani_results(HOS_HTML)
check("history-of-science blocks parse", len(hos) == 2)
check("history-of-science venue is مجلهٔ تاریخ علم",
      all("تاریخ علم" in c["venue"] for c in hos))
check("history-of-science ids extracted",
      {c["oa_pdf_url"].rsplit("/", 1)[1] for c in hos}
      == {"475321", "182095"})

check("empty/garbage pages parse to nothing",
      ba._parse_ensani_results("") == []
      and ba._parse_ensani_results("<html></html>") == [])

# ------------------------------------------------------------- searcher
real_fetch = ba._arab_fetch
try:
    ba._arab_fetch = lambda url, data=None: (200, SEARCH_HTML)
    res = ba.search_ensani("بیرونی")
    check("searcher returns parsed candidates", len(res) == 3)
    check("searcher candidates carry PDF routes",
          all(c["oa_pdf_url"].endswith("/fa/article/download/"
              + c["url"].split("/")[5]) for c in res))
    ba._arab_fetch = lambda url, data=None: (None, "")
    check("searcher fails soft on transport error",
          ba.search_ensani("بیرونی") == [])
    ba._arab_fetch = lambda url, data=None: (500, "err")
    check("searcher fails soft on HTTP 500",
          ba.search_ensani("بیرونی") == [])
    ba._arab_fetch = lambda url, data=None: (200, SEARCH_HTML * 10)
    check("searcher caps at ENSANI_CAP",
          len(ba.search_ensani("بیرونی")) == ba.ENSANI_CAP == 8)
finally:
    ba._arab_fetch = real_fetch

check("searcher registered in SEARCHERS",
      ba.search_ensani in ba.SEARCHERS)
check("searcher registered in WAVE1",
      ba.search_ensani in ba.WAVE1_SEARCHERS)

print(f"\n{passed} passed, {failed} failed")
raise SystemExit(1 if failed else 0)
